targets.root_selector:
def h2i: reduce (explode[]) as $c (0; .*16 + (if $c>=97 then $c-87 elif $c>=65 then $c-55 else $c-48 end));
def fld($h;$i): ($h[64+$i*64:128+$i*64]|h2i) as $off | (64+$off*2) as $lp | ($h[$lp:$lp+64]|h2i) as $len | ($h[$lp+64:$lp+64+$len*2] | [range(0;length/2) as $k | .[$k*2:$k*2+2] | h2i] | implode);
(.result | ltrimstr("0x")) as $h
| (fld($h;1)) as $logo
| { logo: ($logo | if test("^https?://github.com/[^/]+/[^/]+/blob/") then (sub("://github.com/";"://raw.githubusercontent.com/") | sub("/blob/";"/")) else . end) }

def h2i: reduce (explode[]) as $c (0; .*16 + (if $c>=97 then $c-87 elif $c>=65 then $c-55 else $c-48 end));
def fld($h;$i): ($h[64+$i*64:128+$i*64]|h2i) as $off | (64+$off*2) as $lp | ($h[$lp:$lp+64]|h2i) as $len | ($h[$lp+64:$lp+64+$len*2] | [range(0;length/2) as $k | .[$k*2:$k*2+2] | h2i] | implode);
(.result | ltrimstr("0x")) as $h
| { Website: fld($h;2), Twitter: fld($h;5), GitHub: fld($h;7), Email: fld($h;4), Telegram: fld($h;6) }

def h2i: reduce (explode[]) as $c (0; .*16 + (if $c>=97 then $c-87 elif $c>=65 then $c-55 else $c-48 end));
def fld($h;$i): ($h[64+$i*64:128+$i*64]|h2i) as $off | (64+$off*2) as $lp | ($h[$lp:$lp+64]|h2i) as $len | ($h[$lp+64:$lp+64+$len*2] | [range(0;length/2) as $k | .[$k*2:$k*2+2] | h2i] | implode);
(.result | ltrimstr("0x")) as $h
| { Description: fld($h;3) }
